DECLARE
  v_instance_id text;
  v_cooldown_ok boolean;
  v_webhook_payload jsonb;
  v_webhook_url text;
BEGIN
  IF NEW.instance_name != 'wpp2' THEN
    RETURN NEW;
  END IF;

  IF NEW.state NOT IN ('closed', 'disconnected', 'logout') THEN
    RETURN NEW;
  END IF;

  -- Cooldown 5min
  SELECT NOT EXISTS(
    SELECT 1 FROM evo.evolution_bootstrap_log
    WHERE instance_name = NEW.instance_name
      AND created_at > now() - interval '5 minutes'
      AND triggered_by = 'auto-connection-trigger'
  ) INTO v_cooldown_ok;

  IF NOT v_cooldown_ok THEN
    RETURN NEW;
  END IF;

  -- Buscar instanceId
  SELECT id::text INTO v_instance_id
  FROM zapp.evolution_instance_credentials
  WHERE instance_name = NEW.instance_name AND is_active = true
  LIMIT 1;

  -- 1. Registrar diretamente no bootstrap_log (a ação crítica)
  INSERT INTO evo.evolution_bootstrap_log (
    instance_name, instance_id, triggered_by,
    settings_applied, rabbitmq_events_count, status, notes
  ) VALUES (
    NEW.instance_name,
    COALESCE(v_instance_id, 'unknown'),
    'auto-connection-trigger',
    NULL, NULL,
    'registered',
    format('Estado %s→%s detectado em %s. Verificar se instância foi recriada.',
           COALESCE(NEW.previous_state, 'unknown'), NEW.state, NEW.created_at)
  );

  -- 2. Chamar n8n webhook via pg_net para notificação externa
  v_webhook_url := COALESCE(ops.fn_get_vault_secret('n8n_bootstrap_alert_webhook'), 'https://webhook.atomicabr.com.br/webhook/evolution-bootstrap-alert');
  v_webhook_payload := jsonb_build_object(
    'event', 'LOGOUT_INSTANCE',
    'instance', NEW.instance_name,
    'instanceId', COALESCE(v_instance_id, 'unknown'),
    'state', NEW.state,
    'previous_state', NEW.previous_state,
    'detected_at', NEW.created_at
  );

  PERFORM net.http_post(
    url := v_webhook_url,
    body := v_webhook_payload,
    headers := '{"Content-Type":"application/json"}'::jsonb
  );

  RAISE WARNING 'Bootstrap Alert: wpp2 state→%. Bootstrap registered + n8n notified.', NEW.state;

  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  -- Não falhar o INSERT principal por erro no webhook
  RAISE WARNING 'Bootstrap trigger error (non-fatal): %', SQLERRM;
  RETURN NEW;
END;

DECLARE
  v_supabase_url text;
  v_service_key text; v_health_secret text;
  v_row RECORD; v_queued int := 0; v_recovered int := 0;
BEGIN
  v_supabase_url := COALESCE(ops.fn_get_vault_secret('supabase_api_url'), 'https://supabase.atomicabr.com.br');
  SELECT decrypted_secret INTO v_service_key FROM vault.decrypted_secrets WHERE name='supabase_service_role_key' LIMIT 1;
  IF v_service_key IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'JWT nao encontrado no vault'); END IF;
  SELECT decrypted_secret INTO v_health_secret FROM vault.decrypted_secrets WHERE name='health_secret' LIMIT 1;
  IF v_health_secret IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'health_secret nao encontrado no vault'); END IF;
  UPDATE zapp.evolution_whatsapp_status SET media_download_status='pending', media_downloaded_at=NULL
  WHERE media_download_status='processing' AND (media_downloaded_at IS NULL OR media_downloaded_at < now() - interval '15 minutes');
  GET DIAGNOSTICS v_recovered = ROW_COUNT;
  FOR v_row IN
    SELECT id, message_id, participant_jid, media_url FROM zapp.evolution_whatsapp_status
    WHERE media_url LIKE '%mmg.whatsapp.net%' AND media_download_status='pending' AND (expires_at IS NULL OR expires_at > now())
    LIMIT p_batch_size
  LOOP
    UPDATE zapp.evolution_whatsapp_status SET media_download_status='processing', media_downloaded_at=now() WHERE id=v_row.id;
    PERFORM net.http_post(
      url := v_supabase_url || '/functions/v1/download-wa-status-media',
      body := jsonb_build_object('statusId', v_row.id, 'messageId', v_row.message_id, 'mediaUrl', v_row.media_url, 'participantJid', v_row.participant_jid),
      headers := jsonb_build_object('Content-Type', 'application/json', 'Authorization', 'Bearer ' || v_service_key, 'x-internal-secret', v_health_secret),
      timeout_milliseconds := 60000
    );
    v_queued := v_queued + 1;
  END LOOP;
  RETURN jsonb_build_object('ok', true, 'queued', v_queued, 'recovered', v_recovered, 'executed_at', now());
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('ok', false, 'error', SQLERRM);
END;

DECLARE v_lead_status text; v_edge_url text;
BEGIN
  BEGIN
    v_edge_url := COALESCE(ops.fn_get_vault_secret('sicoob_bridge_edge_url'), 'http://functions:9000');
    SELECT lead_status INTO v_lead_status FROM zapp.evolution_contacts WHERE id = NEW.contact_id;
    IF v_lead_status = 'sicoob_gifts' THEN
      PERFORM net.http_post(
        url := v_edge_url || '/sicoob-bridge-reply',
        body := jsonb_build_object('contact_id', NEW.contact_id, 'content', NEW.content, 'message_id', NEW.id, 'created_at', NEW.created_at),
        headers := jsonb_build_object('Content-Type','application/json'));
    END IF;
  EXCEPTION WHEN OTHERS THEN NULL;
  END;
  RETURN NEW;
END

DECLARE
  v_supabase_url text;
  v_service_key  text;
  v_row          record;
  v_res          net.http_response_result;
  v_http         net.http_response;
  v_req_id       bigint;
  v_log_id       bigint;
  v_categoria    text;
  v_ext          text;
  v_url          text;
  v_path_enc     text;
  v_seg          text;
  v_success      boolean;
  v_wait_ms      int := 0;
  v_scanned      int := 0;
  v_enqueued     int := 0;
  v_deleted      int := 0;
  v_failed       int := 0;
  v_pending      int := 0;
  v_skipped      int := 0;
  v_error        int := 0;
BEGIN
  v_supabase_url := COALESCE(ops.fn_get_vault_secret('supabase_api_url'), 'https://supabase.atomicabr.com.br');
  -- Service role key do vault (mesmo padrao das demais funcoes evo.*)
  SELECT decrypted_secret INTO v_service_key
  FROM vault.decrypted_secrets
  WHERE name = 'supabase_service_role_key'
  LIMIT 1;

  -- ============================================================
  -- FASE A: coleta respostas de DELETEs enfileirados em runs ANTERIORES
  -- (pg_net so processa fila COMMITADA: a resposta so fica disponivel
  --  depois que a transacao do run anterior commitou)
  -- ============================================================

/* BULK-STALE-FAIL-2026-08-12: elimina todos os itens stale em 1 UPDATE antes do loop */
  UPDATE evo.media_cleanup_log SET delete_status='failed', deleted_at=now(),
    delete_error='bulk-stale-fail: >2h sem resposta pg_net'
  WHERE delete_status='planned' AND pg_net_request_id IS NOT NULL
    AND planned_at < now() - interval '2 hours';
  GET DIAGNOSTICS v_skipped = ROW_COUNT;
FOR v_row IN
    SELECT id AS log_id, pg_net_request_id AS req_id, planned_at,
           bucket_id, name
    FROM evo.media_cleanup_log
    WHERE delete_status = 'planned'
      AND pg_net_request_id IS NOT NULL
    ORDER BY id
    LIMIT 4   -- FIX-TIMEOUT: limita Phase A a 4 itens por run (max 80s polling)
  LOOP
    -- FIX-TIMEOUT: fast-fail para items stale (>2h sem resposta)
    IF v_row.planned_at < now() - interval '2 hours' THEN
      UPDATE evo.media_cleanup_log
      SET delete_status = 'failed', deleted_at = now(),
          delete_error = 'fast-fail: >2h sem resposta do pg_net worker'
      WHERE id = v_row.log_id;
      v_failed := v_failed + 1;
      CONTINUE;
    END IF;

    -- GUARD R2 (EX-04): nunca processar DELETE de objeto ainda pendente de
    -- migracao R2 (media 'ready' cujo storage_url NAO aponta p/ zapp-media-proxy).
    -- Sem registro de media correspondente (orfao) => purge permitido.
    PERFORM 1
      FROM zapp.evolution_media e
     WHERE e.storage_bucket = v_row.bucket_id
       AND e.storage_path_clean = v_row.name
       AND coalesce(e.storage_url, '') NOT LIKE '%zapp-media-proxy%';
    IF FOUND THEN
      UPDATE evo.media_cleanup_log
         SET delete_status = 'skipped', deleted_at = now(),
             delete_error = 'guard_r2: media ainda referencia storage Supabase (migracao pendente)'
       WHERE id = v_row.log_id;
      v_skipped := v_skipped + 1;
      -- drena a resposta da fila pg_net (best-effort) p/ nao acumular lixo
      PERFORM net._http_collect_response(v_row.req_id, true);
      CONTINUE;
    END IF;

    v_wait_ms := 0;
    v_res := net._http_collect_response(v_row.req_id, true);
    v_http := v_res.response;
    -- wait: polling ate resposta pronta ou erro definitivo (max ~20s)
    WHILE (v_res.status = 'ERROR' OR v_http.status_code IS NULL) AND v_wait_ms < 20000 LOOP
      -- pg_sleep removed: causava statement_timeout (fix R4)
      v_wait_ms := v_wait_ms + 200;
      v_res := net._http_collect_response(v_row.req_id, true);
      v_http := v_res.response;
    END LOOP;

    -- Erro definitivo do worker (timeout/DNS/etc): falha imediata
    IF v_res.status = 'ERROR' AND v_res.message <> 'request matching request_id not found' THEN
      UPDATE evo.media_cleanup_log
      SET delete_status = 'failed', deleted_at = now(), delete_error = left(v_res.message, 300)
      WHERE id = v_row.log_id;
      v_failed := v_failed + 1;
      CONTINUE;
    END IF;

    -- Ainda sem resposta: stale > 1h = falha; recente = fica planned p/ proximo run
    IF v_http.status_code IS NULL THEN
      IF v_row.planned_at < now() - interval '1 hour' THEN
        UPDATE evo.media_cleanup_log
        SET delete_status = 'failed', deleted_at = now(), delete_error = 'pg_net: no response within wait window'
        WHERE id = v_row.log_id;
        v_failed := v_failed + 1;
      ELSE
        v_pending := v_pending + 1;
      END IF;
      CONTINUE;
    END IF;

    -- Sucesso = 2xx, ou 404 (objeto ja inexistente = purge cumprido, idempotente)
    -- Obs.: storage-api devolve HTTP 400 + body {"statusCode":"404","message":"Object not found"} p/ objeto inexistente
    v_success := (v_http.status_code >= 200 AND v_http.status_code < 300)
              OR v_http.status_code = 404
              OR (v_http.body IS NOT NULL
                  AND (v_http.body LIKE '%"statusCode":"404"%' OR v_http.body LIKE '%Object not found%'));

    IF v_success THEN
      UPDATE evo.media_cleanup_log
      SET delete_status = 'deleted', deleted_at = now(), delete_error = NULL
      WHERE id = v_row.log_id;
      v_deleted := v_deleted + 1;
    ELSE
      UPDATE evo.media_cleanup_log
      SET delete_status = 'failed', deleted_at = now(),
          delete_error = 'HTTP ' || coalesce(v_http.status_code::text, '?') || ': ' || left(coalesce(v_http.body, v_res.message, ''), 300)
      WHERE id = v_row.log_id;
      v_failed := v_failed + 1;
    END IF;
  END LOOP;

  -- ============================================================
  -- FASE B: enfileira DELETEs para novos candidatos (fire-and-forget;
  --  respostas serao coletadas no proximo run, fase A)
  -- ============================================================

/* BULK-STALE-FAIL-2026-08-12: elimina todos os itens stale em 1 UPDATE antes do loop */
  UPDATE evo.media_cleanup_log SET delete_status='failed', deleted_at=now(),
    delete_error='bulk-stale-fail: >2h sem resposta pg_net'
  WHERE delete_status='planned' AND pg_net_request_id IS NOT NULL
    AND planned_at < now() - interval '2 hours';
  GET DIAGNOSTICS v_skipped = ROW_COUNT;
FOR v_row IN
    SELECT * FROM evo.fn_list_storage_cache_for_purge(p_days)
  LOOP
    v_scanned := v_scanned + 1;

    -- GUARD R2 (EX-04, defesa em profundidade): nao enfileira DELETE de objeto
    -- ainda pendente de migracao (media apontando p/ storage Supabase)
    PERFORM 1
      FROM zapp.evolution_media e
     WHERE e.storage_bucket = v_row.bucket_name
       AND e.storage_path_clean = v_row.storage_path
       AND coalesce(e.storage_url, '') NOT LIKE '%zapp-media-proxy%';
    IF FOUND THEN
      v_skipped := v_skipped + 1;
      CONTINUE;
    END IF;

    -- Dedupe: objeto ja logado como planned/deleted nao e re-enfileirado
    PERFORM 1 FROM evo.media_cleanup_log l
    WHERE l.bucket_id = v_row.bucket_name AND l.name = v_row.storage_path
      AND l.delete_status IN ('planned', 'deleted', 'failed', 'skipped'); -- fix R4: incluidos failed/skipped para evitar violacao uq
    IF FOUND THEN
      CONTINUE;
    END IF;

    -- Categoria por extensao (padrao da casa: *_antigo)
    v_ext := lower(coalesce(substring(v_row.storage_path from '[.]([A-Za-z0-9]+)$'), ''));
    v_categoria := CASE
      WHEN v_ext IN ('jpg','jpeg','png','gif','webp','heic','heif','bmp','svg','avif','tiff') THEN 'image_antigo'
      WHEN v_ext IN ('mp4','mov','avi','mkv','webm','m4v','3gp','mpeg') THEN 'video_antigo'
      WHEN v_ext IN ('mp3','ogg','opus','wav','aac','m4a','amr','flac') THEN 'audio_antigo'
      WHEN v_ext IN ('pdf','doc','docx','xls','xlsx','ppt','pptx','txt','zip','rar','7z','csv') THEN 'document_antigo'
      ELSE 'other_antigo'
    END;

    -- Registra intencao de purge
    INSERT INTO evo.media_cleanup_log (bucket_id, name, categoria, planned_at, delete_status)
    VALUES (v_row.bucket_name, v_row.storage_path, v_categoria, now(), 'planned')
    RETURNING id INTO v_log_id;

    BEGIN
      -- URL-encode por segmento (preserva '/')
      v_path_enc := '';
      FOR v_seg IN SELECT unnest(string_to_array(v_row.storage_path, '/'))
      LOOP
        v_path_enc := v_path_enc || '/' || net._urlencode_string(v_seg);
      END LOOP;

      v_url := v_supabase_url || '/storage/v1/object/' || net._urlencode_string(v_row.bucket_name) || v_path_enc;

      -- Dispara DELETE assincrono na Storage API (via Kong, service_role)
      SELECT net.http_delete(
        url     := v_url,
        headers := jsonb_build_object('Authorization', 'Bearer ' || coalesce(v_service_key, '')),
        timeout_milliseconds := 15000
      ) INTO v_req_id;

      -- Guarda o request_id p/ coleta da resposta no proximo run
      UPDATE evo.media_cleanup_log
      SET pg_net_request_id = v_req_id
      WHERE id = v_log_id;
      v_enqueued := v_enqueued + 1;
    EXCEPTION WHEN OTHERS THEN
      UPDATE evo.media_cleanup_log
      SET delete_status = 'error', deleted_at = now(), delete_error = left(SQLERRM, 300)
      WHERE id = v_log_id;
      v_error := v_error + 1;
    END;
  END LOOP;

  RETURN jsonb_build_object(
    'ok', true,
    'scanned', v_scanned,
    'enqueued', v_enqueued,
    'deleted', v_deleted,
    'failed', v_failed,
    'pending', v_pending,
    'skipped', v_skipped,
    'errors', v_error,
    'executed_at', now()
  );
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('ok', false, 'error', SQLERRM);
END;

DECLARE
  v_pwd    text;
  v_conn   text;
  v_result record;
BEGIN
  -- Prioridade 1: parametro explicito
  IF p_pg_password IS NOT NULL THEN
    v_pwd := p_pg_password;
  ELSE
    -- Prioridade 2: Vault (fonte segura, criptografada)
    SELECT decrypted_secret INTO v_pwd
    FROM vault.decrypted_secrets
    WHERE name='evolution_pg_password';

    -- Prioridade 3: _secure_config (fallback, apenas se vault vazio)
    IF v_pwd IS NULL THEN
      SELECT value INTO v_pwd FROM evo._secure_config WHERE key='evolution_pg_password';
    END IF;
  END IF;

  -- Validar: rejeitar se vazio ou marcado como migrado
  IF v_pwd IS NULL OR v_pwd LIKE '[%' OR length(trim(v_pwd)) < 8 THEN
    RETURN jsonb_build_object('status','error','message',
      'evolution_pg_password indisponivel (verifique vault.secrets name=evolution_pg_password)',
      'checked_at', now());
  END IF;

  -- FIX 2026-08-06 (E9): hostname do servico em vez de VIP hardcoded 10.0.1.48 (stale).
  -- VIP atual do servico postgres (PG14 evolution) = 10.0.1.118; hostname resolve via overlay.
  v_conn := 'host=postgres port=5432 dbname=evolution user=postgres password='
            || v_pwd || ' connect_timeout=5';

  -- Ler ultimo heartbeat do guardian do Evolution DB via dblink
  SELECT * INTO v_result FROM dblink(
    v_conn,
    'SELECT detected_at, case_kind
     FROM _swarm_guardian_events
     WHERE case_kind=''guardian_start''
     ORDER BY detected_at DESC LIMIT 1'
  ) AS t(detected_at timestamptz, case_kind text);

  IF v_result.detected_at IS NULL THEN
    RETURN jsonb_build_object('status','no_heartbeat','checked_at',now());
  END IF;

  -- Inserir com ON CONFLICT DO NOTHING para evitar duplicatas
  INSERT INTO evo.evolution_guardian_heartbeat(service_name, heartbeat_at, details)
  VALUES (
    'swarm-task-guardian',
    v_result.detected_at,
    jsonb_build_object(
      'source', 'dblink',
      'alive',  (EXTRACT(EPOCH FROM (now() - v_result.detected_at)) < 600),
      'age_s',  EXTRACT(EPOCH FROM (now() - v_result.detected_at))::int
    )
  )
  ON CONFLICT (service_name, heartbeat_at) DO NOTHING;

  RETURN jsonb_build_object(
    'status',        'ok',
    'heartbeat_at',  v_result.detected_at,
    'age_s',         EXTRACT(EPOCH FROM (now() - v_result.detected_at))::int,
    'source',        'vault'
  );
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('status','error','message',SQLERRM,'checked_at',now());
END;

DECLARE
  v_supabase_url    text;
  v_service_key     text;
  v_health_secret   text;
  v_row             RECORD;
  v_request_id      bigint;
  v_queued          int := 0;
  v_recovered       int := 0;
  v_in_processing   int := 0;
  MAX_CONCURRENT    CONSTANT int := 15;
BEGIN
  v_supabase_url := COALESCE(ops.fn_get_vault_secret('supabase_api_url'), 'https://supabase.atomicabr.com.br');
  SELECT decrypted_secret INTO v_service_key
    FROM vault.decrypted_secrets WHERE name='supabase_service_role_key' LIMIT 1;
  IF v_service_key IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'JWT nao encontrado no vault');
  END IF;

  SELECT decrypted_secret INTO v_health_secret FROM vault.decrypted_secrets WHERE name='health_secret' LIMIT 1;
  IF v_health_secret IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'health_secret nao encontrado no vault');
  END IF;

  UPDATE zapp.evolution_messages_wpp2
     SET transcription_status = 'queued', updated_at = now()
   WHERE message_type IN ('audio', 'audioMessage')
     AND transcription_status = 'processing'
     AND updated_at < now() - interval '15 minutes';
  GET DIAGNOSTICS v_recovered = ROW_COUNT;

  UPDATE zapp.evolution_messages_wpp2
     SET transcription_status = 'queued', media_status = 'ready', updated_at = now()
   WHERE message_type IN ('audio', 'audioMessage')
     AND transcription_status = 'expired'
     AND media_status IN ('expired', 'ready')
     AND media_url LIKE '%supabase.atomicabr.com.br/storage%'
     AND media_url IS NOT NULL;

  UPDATE zapp.evolution_messages_wpp2
     SET transcription_status = 'queued', error_code = NULL, error_reason = NULL, updated_at = now()
   WHERE message_type IN ('audio', 'audioMessage')
     AND transcription_status = 'failed'
     AND error_code = 'concurrent_limit_exceeded'
     AND updated_at < now() - interval '10 minutes';

  SELECT COUNT(*) INTO v_in_processing
    FROM zapp.evolution_messages_wpp2
   WHERE message_type IN ('audio', 'audioMessage')
     AND transcription_status = 'processing';

  IF v_in_processing >= MAX_CONCURRENT THEN
    RETURN jsonb_build_object(
      'ok', true, 'queued', 0, 'recovered', v_recovered,
      'skipped', true, 'reason', 'concurrent_limit_guard',
      'in_processing', v_in_processing, 'max_concurrent', MAX_CONCURRENT,
      'executed_at', now()
    );
  END IF;

  p_batch_size := LEAST(p_batch_size, GREATEST(0, MAX_CONCURRENT - v_in_processing));

  FOR v_row IN
    SELECT message_id, media_url
      FROM zapp.evolution_messages_wpp2
     WHERE message_type IN ('audio', 'audioMessage')
       AND media_status = 'ready'
       AND media_url IS NOT NULL
       AND (transcription_status IS NULL OR transcription_status = 'queued')
     ORDER BY created_at ASC
     LIMIT p_batch_size
  LOOP
    UPDATE zapp.evolution_messages_wpp2
       SET transcription_status = 'processing', updated_at = now()
     WHERE message_id = v_row.message_id;

    SELECT net.http_post(
      url                  := v_supabase_url || '/functions/v1/transcribe-audio-internal',
      body                 := jsonb_build_object('messageId', v_row.message_id, 'audioUrl', v_row.media_url),
      headers              := jsonb_build_object(
        'Content-Type',     'application/json',
        'Authorization',    'Bearer ' || v_service_key,
        'x-internal-secret', v_health_secret
      ),
      timeout_milliseconds := 120000
    ) INTO v_request_id;

    v_queued := v_queued + 1;
  END LOOP;

  IF v_queued = 0 THEN
    RETURN jsonb_build_object(
      'ok', true, 'queued', 0, 'recovered', v_recovered,
      'in_processing', v_in_processing,
      'message', 'Nenhum audio pendente', 'executed_at', now()
    );
  END IF;

  RETURN jsonb_build_object(
    'ok', true, 'queued', v_queued, 'recovered', v_recovered,
    'in_processing', v_in_processing,
    'first_request_id', v_request_id,
    'timeout_ms', 120000, 'executed_at', now()
  );
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('ok', false, 'error', SQLERRM);
END;

DECLARE r record; v_state ops.wal_alert_state; v_acao text := ''; v_url text;
BEGIN
  v_url := COALESCE(ops.fn_get_vault_secret('n8n_warroom_alert_webhook'), 'https://n8n.atomicabr.com.br/webhook/warroom-alert');
  FOR r IN
    SELECT slot_name,
           coalesce((pg_wal_lsn_diff(pg_current_wal_lsn(), restart_lsn)/1024/1024)::int, 0) AS mb
    FROM pg_replication_slots
  LOOP
    SELECT * INTO v_state FROM ops.wal_alert_state WHERE slot_name = r.slot_name;
    IF NOT FOUND THEN
      INSERT INTO ops.wal_alert_state(slot_name, last_mb) VALUES (r.slot_name, r.mb)
      RETURNING * INTO v_state;
    END IF;

    IF r.mb > 512 AND NOT v_state.alerting THEN
      UPDATE ops.wal_alert_state SET alerting=true, last_mb=r.mb, alerted_at=now(), updated_at=now() WHERE slot_name=r.slot_name;
      PERFORM net.http_post(
        url := v_url,
        headers := '{"Content-Type":"application/json"}'::jsonb,
        body := jsonb_build_object('service','wal-slot-monitor','event','critical',
          'detail', format('Replication slot %s retendo %s MB de WAL (limite 512MB). Risco de disco cheio. Verificar consumidor (cainophile/realtime).', r.slot_name, r.mb)),
        timeout_milliseconds := 10000);
      v_acao := v_acao || format('[ALERTA %s=%sMB]', r.slot_name, r.mb);
    ELSIF r.mb < 256 AND v_state.alerting THEN
      UPDATE ops.wal_alert_state SET alerting=false, last_mb=r.mb, resolved_at=now(), updated_at=now() WHERE slot_name=r.slot_name;
      PERFORM net.http_post(
        url := v_url,
        headers := '{"Content-Type":"application/json"}'::jsonb,
        body := jsonb_build_object('service','wal-slot-monitor','event','recovery',
          'detail', format('Slot %s normalizado: %s MB retidos.', r.slot_name, r.mb)),
        timeout_milliseconds := 10000);
