DECLARE
  v_cfg        record;
  v_alert      record;
  v_url        text;
  v_key        text;
  v_resend_key text;
  v_resend_url text;
  v_ext_url    text;
  v_payload    jsonb;
  v_sent       int := 0;
  v_conn_ok    boolean := false;
BEGIN
  SELECT * INTO v_cfg FROM ops.notification_config WHERE id=1 AND enabled;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok',false,'reason','config_ausente_ou_desabilitada');
  END IF;

  v_url        := ops.fn_evo_url();
  v_key        := ops.fn_evo_key();
  SELECT decrypted_secret INTO v_resend_key FROM vault.decrypted_secrets WHERE name='resend_api_key';
  SELECT decrypted_secret INTO v_ext_url FROM vault.decrypted_secrets WHERE name='external_notification_url';
  v_resend_url := COALESCE(ops.fn_get_vault_secret('resend_api_url'), 'https://api.resend.com');

  -- Verificar se wpp2 está conectado (guard de sessão)
  SELECT (wc.status='connected' AND wc.updated_at > now()-interval '10 minutes')
  INTO v_conn_ok
  FROM zapp.whatsapp_connections wc
  WHERE wc.instance_name = coalesce(v_cfg.instance,'wpp2')
  LIMIT 1;

  FOR v_alert IN
    SELECT * FROM ops.pending_critical_alerts
    WHERE notified_at IS NULL
    ORDER BY created_at
    LIMIT 5
  LOOP
    -- Canal WhatsApp
    IF coalesce(v_conn_ok, false) AND v_url IS NOT NULL AND v_key IS NOT NULL THEN
      PERFORM net.http_post(
        url     := rtrim(v_url,'/')||'/message/sendText/'||v_cfg.instance,
        headers := jsonb_build_object('Content-Type','application/json','apikey',v_key),
        body    := jsonb_build_object(
          'number', v_cfg.target_jid,
          'text',   chr(128680)||' *ALERTA CRITICO ZAPP WEBB*'||chr(10)||chr(10)
                    ||'*'||coalesce(v_alert.title,v_alert.alert_type)||'*'||chr(10)
                    ||coalesce(v_alert.message,'')||chr(10)||chr(10)
                    ||chr(9200)||' '||to_char(v_alert.created_at AT TIME ZONE 'America/Sao_Paulo','DD/MM HH24:MI')
                    ||chr(10)||'#'||v_alert.alert_type),
        params  := '{}',
        timeout_milliseconds := 5000
      );
    END IF;

    -- Canal webhook externo
    IF v_ext_url IS NOT NULL AND v_ext_url <> '' THEN
      PERFORM net.http_post(
        url     := v_ext_url,
        headers := jsonb_build_object('Content-Type','application/json'),
        body    := jsonb_build_object(
          'severity',   'critical',
          'alert_type', v_alert.alert_type,
          'message',    coalesce(v_alert.message,''),
          'title',      coalesce(v_alert.title,v_alert.alert_type),
          'created_at', v_alert.created_at::text,
          'source',     'fn_notify_critical_alerts_v6'),
        params  := '{}',
        timeout_milliseconds := 5000
      );
    END IF;

    -- Canal email Resend
    IF v_resend_key IS NOT NULL THEN
      PERFORM net.http_post(
        url     := v_resend_url || '/emails',
        headers := jsonb_build_object('Authorization','Bearer '||v_resend_key,'Content-Type','application/json'),
        body    := jsonb_build_object(
          'from',    'AtomicaBR Alertas <alertas@promobrindes.com.br>',
          'to',      ARRAY['ti@promobrindes.com.br'],
          'subject', chr(128680)||' [CRITICO] '||coalesce(v_alert.title,v_alert.alert_type),
          'html',    '<div style="font-family:Arial,sans-serif">'
                     ||'<div style="background:#c0392b;padding:16px;border-radius:6px 6px 0 0">'
                     ||'<h2 style="color:#fff;margin:0">Alerta Critico ZAP WEBB</h2></div>'
                     ||'<div style="padding:20px;border:1px solid #ddd">'
                     ||'<p><b>Tipo:</b> '||coalesce(v_alert.alert_type,'?')||'</p>'
                     ||'<p><b>Titulo:</b> '||coalesce(v_alert.title,'?')||'</p>'
                     ||'<p><b>Mensagem:</b><br>'||replace(coalesce(v_alert.message,'?'),chr(10),'<br>')||'</p>'
                     ||'<hr><p style="color:#999;font-size:12px">'
                     ||to_char(v_alert.created_at AT TIME ZONE 'America/Sao_Paulo','DD/MM/YYYY HH24:MI:SS')
                     ||' BRT — ops.fn_notify_critical_alerts v6</p></div></div>'),
        params  := '{}',
        timeout_milliseconds := 10000
      );
    END IF;

    -- Marcar como notificado na VIEW (propaga para zapp.evolution_alerts)
    UPDATE ops.pending_critical_alerts
    SET notified_at = now()
    WHERE id = v_alert.id;

    v_sent := v_sent + 1;
  END LOOP;

  RETURN jsonb_build_object(
    'ok',           true,
    'sent',         v_sent,
    'wpp_session',  v_conn_ok,
    'triple_channel', true,
    'version',      'v6-fix-pending-view-20260814'
  );
EXCEPTION WHEN OTHERS THEN
  -- Apenas exceções reais chegam aqui (VIEW existe, v_conn_ok declarado)
  RETURN jsonb_build_object('ok',false,'error',SQLERRM,'version','v6');
END;

DECLARE
  v_http_code int;
  v_body      text;
  v_status    text;
  v_falhas    int;
  v_license_url text;
BEGIN
  v_license_url := COALESCE(ops.fn_evo_url_v2(), 'https://evolution.atomicabr.com.br') || '/license/status';
  PERFORM net.http_get(v_license_url);
  PERFORM pg_sleep(7);

  SELECT status_code, content::text
  INTO v_http_code, v_body
  FROM net._http_response
  WHERE created > now() - interval '30 seconds'
  ORDER BY id DESC
  LIMIT 1;

  v_status := CASE
    WHEN v_http_code = 200 AND (v_body ~ '"ok"\s*:\s*true' OR v_body ~ '"status"\s*:\s*"active"') THEN 'active'
    WHEN v_http_code = 200 AND v_body !~ '"status"' AND v_body ~ '"ok"\s*:\s*true' THEN 'active'
    ELSE COALESCE(v_body, 'sem_resposta')
  END;

  INSERT INTO zapp.license_heartbeat_log (checked_at, status, http_code, raw)
  VALUES (now(), v_status, COALESCE(v_http_code, 0), left(COALESCE(v_body, ''), 500));

  IF v_status <> 'active' OR v_http_code IS DISTINCT FROM 200 THEN
    SELECT count(*) INTO v_falhas
    FROM zapp.license_heartbeat_log
    WHERE checked_at > now() - interval '1 hour' AND status <> 'active';

    IF v_falhas >= 3 THEN
      INSERT INTO zapp.evolution_alerts (alert_type, severity, title, message, payload, created_at)
      SELECT 'license_heartbeat', 'critical', 'License Evolution INATIVA',
        'Heartbeat falhou ' || v_falhas || 'x/hora. HTTP=' ||
        COALESCE(v_http_code::text,'NULL') || ' status=' || left(COALESCE(v_status,'?'),100),
        jsonb_build_object('http_code',v_http_code,'status',v_status,'raw',left(COALESCE(v_body,''),500)), now()
      WHERE NOT EXISTS (
        SELECT 1 FROM zapp.evolution_alerts ea2
        WHERE ea2.alert_type = 'license_heartbeat'
          AND ea2.resolved_at IS NULL AND ea2.created_at > now() - interval '2 hours'
      );
    END IF;
  END IF;

  RETURN v_status;
END;

DECLARE
  v_api_key text;
  v_portainer_url text;
  v_containers_req_id bigint;
  v_containers_response jsonb;
  v_container_id text;
  v_logs_req_id bigint;
  v_logs_response text;
  v_ingest jsonb;
BEGIN
  v_portainer_url := COALESCE(ops.fn_get_vault_secret('portainer_api_url'), 'https://portainer.atomicabr.com.br');

  SELECT decrypted_secret INTO v_api_key
  FROM vault.decrypted_secrets
  WHERE name = 'portainer_api_key' LIMIT 1;

  IF v_api_key IS NULL THEN
    RETURN jsonb_build_object('status','standby','reason','portainer_api_key_not_in_vault');
  END IF;

  SELECT net.http_get(
    url := v_portainer_url || '/api/endpoints/' || p_endpoint_id || '/docker/containers/json?all=true&filters=' ||
           replace(replace(jsonb_build_object('name', jsonb_build_array(p_container_name))::text, '"', '%22'), ' ', ''),
    headers := jsonb_build_object('X-API-Key', v_api_key),
    timeout_milliseconds := 10000
  ) INTO v_containers_req_id;

  FOR i IN 1..16 LOOP
    PERFORM pg_sleep(0.5);
    SELECT (content::jsonb) INTO v_containers_response
    FROM net._http_response
    WHERE id = v_containers_req_id AND status_code IS NOT NULL LIMIT 1;
    EXIT WHEN v_containers_response IS NOT NULL;
  END LOOP;

  IF v_containers_response IS NULL OR jsonb_array_length(v_containers_response) = 0 THEN
    RETURN jsonb_build_object('status','no_container_found','container_name', p_container_name);
  END IF;

  v_container_id := v_containers_response->0->>'Id';

  SELECT net.http_get(
    url := v_portainer_url || '/api/endpoints/' || p_endpoint_id || '/docker/containers/' || v_container_id ||
           '/logs?stdout=true&stderr=true&tail=500',
    headers := jsonb_build_object('X-API-Key', v_api_key),
    timeout_milliseconds := 15000
  ) INTO v_logs_req_id;

  FOR i IN 1..30 LOOP
    PERFORM pg_sleep(0.5);
    SELECT content INTO v_logs_response
    FROM net._http_response
    WHERE id = v_logs_req_id AND status_code IS NOT NULL LIMIT 1;
    EXIT WHEN v_logs_response IS NOT NULL;
  END LOOP;

  IF v_logs_response IS NULL THEN
    RETURN jsonb_build_object('status','timeout_reading_logs');
  END IF;

  v_logs_response := regexp_replace(v_logs_response, E'[\\x00-\\x08\\x0B-\\x1F]', '', 'g');
  v_ingest := zapp.fn_ingest_restore_logs_from_text(v_logs_response);

  RETURN jsonb_build_object('status','ok','container_id', v_container_id,'logs_bytes', length(v_logs_response),'ingest', v_ingest);
END;

DECLARE
  v_lusha_cookie  TEXT;
  v_lusha_token   TEXT;
  v_lc_cookie     TEXT;
  v_lc_token      TEXT;
  v_li_cookie     TEXT;
  v_li_csrf       TEXT;
  v_req_lusha     BIGINT;
  v_req_lc        BIGINT;
  v_req_li        BIGINT;
  v_fired         INT  := 0;
  v_lusha_mode    TEXT := 'v2_cookie';
  v_lc_auth       TEXT := 'none';
  v_lusha_v3_url  TEXT;
  v_lusha_v2_url  TEXT;
  v_lc_url        TEXT;
  v_li_url        TEXT;
BEGIN
  v_lusha_v3_url := COALESCE(ops.fn_get_vault_secret('lusha_v3_api_url'), 'https://api.lusha.com');
  v_lusha_v2_url := COALESCE(ops.fn_get_vault_secret('lusha_v2_api_url'), 'https://dashboard-services.lusha.com');
  v_lc_url := COALESCE(ops.fn_get_vault_secret('leadcontact_api_url'), 'https://api.leadcontact.ai');
  v_li_url := COALESCE(ops.fn_get_vault_secret('linkedin_api_url'), 'https://www.linkedin.com');
  SELECT cookie, token INTO v_lusha_cookie, v_lusha_token FROM zapp.cookies_config WHERE servico='lusha';
  SELECT cookie, token INTO v_lc_cookie, v_lc_token FROM zapp.cookies_config WHERE servico='leadcontact';
  SELECT cookie, csrf_token INTO v_li_cookie, v_li_csrf FROM zapp.cookies_config WHERE servico='linkedin';

  -- █ LUSHA probe — DUAL MODE: V3 (api_key) se token>=32 chars, else V2 (JWT cookie)
  IF length(coalesce(v_lusha_token,'')) >= 32 THEN
    -- V3: GET api.lusha.com/v3 com api_key header (sem cookie JWT)
    v_lusha_mode := 'v3_apikey';
    SELECT net.http_get(
      url := v_lusha_v3_url || '/v3/contacts/prospecting/filters/departments',
      headers := jsonb_build_object(
        'api_key', v_lusha_token,
        'Accept', 'application/json',
        'User-Agent', 'Mozilla/5.0'),
      timeout_milliseconds := 6000
    ) INTO v_req_lusha;
    INSERT INTO zapp.cookie_probe_pending(servico,request_id,dispatched_at,probe_version,probe_auth)
    VALUES('lusha',v_req_lusha,now(),'v3','apikey')
    ON CONFLICT (servico) DO UPDATE SET request_id=EXCLUDED.request_id,dispatched_at=EXCLUDED.dispatched_at,probe_version='v3',probe_auth='apikey';
    v_fired := v_fired+1;
  ELSIF length(coalesce(v_lusha_cookie,'')) > 20 THEN
    -- V2: GET dashboard-services.lusha.com/v2 com Cookie JWT (modo atual)
    v_lusha_mode := 'v2_cookie';
    SELECT net.http_get(
      url := v_lusha_v2_url || '/v2/filters/companyName?text=PROBE',
      headers := jsonb_build_object(
        'Cookie',v_lusha_cookie,'Origin','https://dashboard.lusha.com',
        'Referer','https://dashboard.lusha.com/','Accept','application/json',
        'User-Agent','Mozilla/5.0 (Windows NT 10.0; Win64; x64)'),
      timeout_milliseconds := 6000
    ) INTO v_req_lusha;
    INSERT INTO zapp.cookie_probe_pending(servico,request_id,dispatched_at,probe_version,probe_auth)
    VALUES('lusha',v_req_lusha,now(),'v2','cookie')
    ON CONFLICT (servico) DO UPDATE SET request_id=EXCLUDED.request_id,dispatched_at=EXCLUDED.dispatched_at,probe_version='v2',probe_auth='cookie';
    v_fired := v_fired+1;
  END IF;

  -- █ LEADCONTACT probe — Bearer primary, SESSION fallback
  IF length(coalesce(v_lc_token,'')) > 10 OR length(coalesce(v_lc_cookie,'')) > 10 THEN
    v_lc_auth := CASE WHEN length(coalesce(v_lc_token,'')) > 10 THEN 'bearer' ELSE 'cookie' END;
    SELECT net.http_post(
      url := v_lc_url || '/api/auth/check_login',
      body := '{}'::jsonb,
      headers := CASE
        WHEN length(coalesce(v_lc_token,'')) > 10
        THEN jsonb_build_object(
          'Authorization','Bearer '||v_lc_token,'Content-Type','application/json',
          'Origin','chrome-extension://imhlnhlbiencamnbpigopiibddajimep','User-Agent','Mozilla/5.0')
        ELSE jsonb_build_object(
          'Cookie',v_lc_cookie,'Content-Type','application/json',
          'Origin','chrome-extension://imhlnhlbiencamnbpigopiibddajimep','User-Agent','Mozilla/5.0')
      END,
      timeout_milliseconds := 6000
    ) INTO v_req_lc;
    INSERT INTO zapp.cookie_probe_pending(servico,request_id,dispatched_at,probe_version,probe_auth)
    VALUES('leadcontact',v_req_lc,now(),'v1',v_lc_auth)
    ON CONFLICT (servico) DO UPDATE SET request_id=EXCLUDED.request_id,dispatched_at=EXCLUDED.dispatched_at,probe_auth=EXCLUDED.probe_auth;
    v_fired := v_fired+1;
  END IF;

  -- █ LINKEDIN probe — inalterado (cookie morto, circuit aberto, monitor)
  IF length(coalesce(v_li_cookie,'')) > 20 THEN
    SELECT net.http_get(
      url := v_li_url || '/voyager/api/me',
      headers := jsonb_build_object(
        'Cookie',v_li_cookie,'csrf-token',coalesce(v_li_csrf,''),
        'Accept','application/vnd.linkedin.normalized+json+2.1',
        'x-restli-protocol-version','2.0.0','User-Agent','Mozilla/5.0 (Windows NT 10.0; Win64; x64)'),
      timeout_milliseconds := 6000
    ) INTO v_req_li;
    INSERT INTO zapp.cookie_probe_pending(servico,request_id,dispatched_at,probe_version,probe_auth)
    VALUES('linkedin',v_req_li,now(),'v1','cookie')
    ON CONFLICT (servico) DO UPDATE SET request_id=EXCLUDED.request_id,dispatched_at=EXCLUDED.dispatched_at;
    v_fired := v_fired+1;
  END IF;

  RETURN jsonb_build_object(
    'phase','dispatch','fired',v_fired,
    'lusha_mode',v_lusha_mode,'lc_auth',v_lc_auth,
    'req_ids',jsonb_build_object('lusha',v_req_lusha,'leadcontact',v_req_lc,'linkedin',v_req_li),
    'dispatched_at',now());
END;

DECLARE
  v_lusha_cookie TEXT;
  v_lc_cookie    TEXT;
  v_li_cookie    TEXT;
  v_li_csrf      TEXT;
  v_req_lusha    BIGINT;
  v_req_lc       BIGINT;
  v_req_li       BIGINT;
  v_total_reqs   INT := 0;
  v_done         INT;
  v_i            INT;
  v_status       INT;
  v_content      TEXT;
  v_healthy      BOOLEAN;
  v_started      TIMESTAMPTZ := clock_timestamp();
  v_lusha_v2_url TEXT;
  v_lc_url       TEXT;
  v_li_url       TEXT;
BEGIN
  v_lusha_v2_url := COALESCE(ops.fn_get_vault_secret('lusha_v2_api_url'), 'https://dashboard-services.lusha.com');
  v_lc_url := COALESCE(ops.fn_get_vault_secret('leadcontact_api_url'), 'https://api.leadcontact.ai');
  v_li_url := COALESCE(ops.fn_get_vault_secret('linkedin_api_url'), 'https://www.linkedin.com');

  SELECT cookie INTO v_lusha_cookie FROM zapp.cookies_config WHERE servico='lusha';
  SELECT cookie INTO v_lc_cookie    FROM zapp.cookies_config WHERE servico='leadcontact';
  SELECT cookie, csrf_token INTO v_li_cookie, v_li_csrf
    FROM zapp.cookies_config WHERE servico='linkedin';

  IF length(coalesce(v_lusha_cookie,'')) > 20 THEN
    SELECT net.http_get(
      url     := v_lusha_v2_url || '/v2/filters/companyName?text=PROBE',
      headers := jsonb_build_object(
        'Cookie',     v_lusha_cookie,
        'Origin',     'https://dashboard.lusha.com',
        'Referer',    'https://dashboard.lusha.com/',
        'Accept',     'application/json',
        'User-Agent', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64)'
      ),
      timeout_milliseconds := 6000
    ) INTO v_req_lusha;
    v_total_reqs := v_total_reqs + 1;
  END IF;

  IF length(coalesce(v_lc_cookie,'')) > 10 THEN
    SELECT net.http_post(
      url     := v_lc_url || '/api/auth/check_login',
      body    := '{}'::jsonb,
      headers := jsonb_build_object(
        'Cookie',       v_lc_cookie,
        'Content-Type', 'application/json',
        'Origin',       'chrome-extension://imhlnhlbiencamnbpigopiibddajimep',
        'User-Agent',   'Mozilla/5.0'
      ),
      timeout_milliseconds := 6000
    ) INTO v_req_lc;
    v_total_reqs := v_total_reqs + 1;
  END IF;

  IF length(coalesce(v_li_cookie,'')) > 20 THEN
    SELECT net.http_get(
      url     := v_li_url || '/voyager/api/me',
      headers := jsonb_build_object(
        'Cookie',                    v_li_cookie,
        'csrf-token',                coalesce(v_li_csrf,''),
        'Accept',                    'application/vnd.linkedin.normalized+json+2.1',
        'x-restli-protocol-version', '2.0.0',
        'User-Agent',                'Mozilla/5.0 (Windows NT 10.0; Win64; x64)'
      ),
      timeout_milliseconds := 6000
    ) INTO v_req_li;
    v_total_reqs := v_total_reqs + 1;
  END IF;

  v_i := 0;
  LOOP
    EXIT WHEN v_i >= 18;
    PERFORM pg_sleep(0.5);
    v_i := v_i + 1;

    SELECT count(*) INTO v_done
    FROM net._http_response
    WHERE id IN (v_req_lusha, v_req_lc, v_req_li)
      AND status_code IS NOT NULL;

    EXIT WHEN v_done >= v_total_reqs;
  END LOOP;

  IF v_req_lusha IS NOT NULL THEN
    SELECT r.status_code, left(r.content::text, 300)
      INTO v_status, v_content
    FROM net._http_response r WHERE r.id = v_req_lusha;

    v_healthy := coalesce(v_status,0) = 200;
    UPDATE zapp.cookies_config SET
      is_healthy           = v_healthy,
      health_status        = CASE coalesce(v_status,0)
                               WHEN 200 THEN 'healthy'
                               WHEN 401 THEN 'expired'
                               WHEN 403 THEN 'challenged'
                               WHEN 429 THEN 'rate_limited'
                               ELSE       'error' END,
      health_error         = format('real_probe v2 http=%s at %s | head=%s',
                               coalesce(v_status::text,'timeout'), now(),
                               left(coalesce(v_content,''),80)),
      last_health_check_at = now()
    WHERE servico = 'lusha';

    INSERT INTO zapp.cookie_probe_log (servico, http_status, response_preview, is_healthy, probe_ms)
    VALUES ('lusha', v_status, left(coalesce(v_content,''),200), v_healthy,
            (extract(epoch from clock_timestamp()-v_started)*1000)::int);

    PERFORM zapp.fn_circuit_record('lusha', v_healthy);
  END IF;

  IF v_req_lc IS NOT NULL THEN
    SELECT r.status_code, left(r.content::text, 300)
      INTO v_status, v_content
    FROM net._http_response r WHERE r.id = v_req_lc;

    BEGIN
      v_healthy := coalesce(v_status,0)=200
                   AND (v_content::jsonb->'data'->>'login')='true';
    EXCEPTION WHEN OTHERS THEN
      v_healthy := false;
    END;

    UPDATE zapp.cookies_config SET
      is_healthy           = v_healthy,
      health_status        = CASE
                               WHEN v_healthy               THEN 'healthy'
                               WHEN coalesce(v_status,0)=0  THEN 'error'
                               ELSE 'expired' END,
      health_error         = format('real_probe v2 http=%s login=%s at %s',
                               coalesce(v_status::text,'timeout'),
                               CASE WHEN v_healthy THEN 'true' ELSE 'false' END,
                               now()),
      last_health_check_at = now()
    WHERE servico = 'leadcontact';

    INSERT INTO zapp.cookie_probe_log (servico, http_status, response_preview, is_healthy, probe_ms)
    VALUES ('leadcontact', v_status, left(coalesce(v_content,''),200), v_healthy,
            (extract(epoch from clock_timestamp()-v_started)*1000)::int);

    PERFORM zapp.fn_circuit_record('leadcontact', v_healthy);
  END IF;

  IF v_req_li IS NOT NULL THEN
    SELECT r.status_code, left(r.content::text, 200)
      INTO v_status, v_content
    FROM net._http_response r WHERE r.id = v_req_li;

    v_healthy := coalesce(v_status,0) = 200;
    UPDATE zapp.cookies_config SET
      is_healthy           = v_healthy,
      health_status        = CASE coalesce(v_status,0)
                               WHEN 200 THEN 'healthy'
                               WHEN 302 THEN 'expired'
                               WHEN 400 THEN 'expired'
                               WHEN 403 THEN 'challenged'
                               WHEN 429 THEN 'rate_limited'
                               ELSE       'error' END,
      health_error         = format('real_probe v2 http=%s at %s',
                               coalesce(v_status::text,'timeout'), now()),
      last_health_check_at = now()
    WHERE servico = 'linkedin';

    INSERT INTO zapp.cookie_probe_log (servico, http_status, response_preview, is_healthy, probe_ms)
    VALUES ('linkedin', v_status, left(coalesce(v_content,''),200), v_healthy,
            (extract(epoch from clock_timestamp()-v_started)*1000)::int);

    PERFORM zapp.fn_circuit_record('linkedin', v_healthy);
  END IF;

  RETURN jsonb_build_object(
    'probed_at',   v_started,
    'duration_ms', (extract(epoch from clock_timestamp()-v_started)*1000)::int,
    'requests_fired', v_total_reqs,
    'iterations_used', v_i,
    'req_ids', jsonb_build_object(
      'lusha', v_req_lusha, 'leadcontact', v_req_lc, 'linkedin', v_req_li
    )
  );
END;

DECLARE v_url text; v_alerts jsonb; v_count int; v_req bigint;
BEGIN
  SELECT count(*), jsonb_agg(jsonb_build_object('tipo',alert_type,'sev',severity,'msg',message,'quando',created_at) ORDER BY created_at DESC)
    INTO v_count, v_alerts
  FROM zapp.evolution_alerts
  WHERE coalesce(acknowledged,false)=false AND escalated_at IS NULL AND severity='critical';

  IF v_count = 0 THEN
    RETURN jsonb_build_object('escalated',0,'reason','sem alertas criticos novos');
  END IF;

  BEGIN
    SELECT decrypted_secret INTO v_url FROM vault.decrypted_secrets WHERE name='alerts_webhook_url';
  EXCEPTION WHEN OTHERS THEN v_url := NULL; END;

  IF v_url IS NULL OR v_url = '' THEN
    UPDATE zapp.evolution_alerts SET escalated_at=now()
      WHERE coalesce(acknowledged,false)=false AND escalated_at IS NULL AND severity='critical';
    RETURN jsonb_build_object('escalated',v_count,'delivered',false,'reason','configure vault.alerts_webhook_url para entregar');
  END IF;

  v_req := net.http_post(
    url := v_url,
    headers := jsonb_build_object('Content-Type','application/json'),
    body := jsonb_build_object('source','supabase-evolution-watchdog','severity','critical','count',v_count,'alerts',v_alerts,'at',now()),
    timeout_milliseconds := 8000);

  UPDATE zapp.evolution_alerts SET escalated_at=now()
    WHERE coalesce(acknowledged,false)=false AND escalated_at IS NULL AND severity='critical';

  RETURN jsonb_build_object('escalated',v_count,'delivered',true,'net_request_id',v_req);
END;

DECLARE
  v_secret text;
BEGIN
  SELECT decrypted_secret INTO v_secret
  FROM vault.decrypted_secrets
  WHERE name = p_name
  LIMIT 1;
  RETURN v_secret;
END

DECLARE
  v_severity_rank   smallint;
  v_cooldown_row    zapp.evolution_alert_cooldown%ROWTYPE;
  v_webhook_url     text;
  v_recipient_id    text;
  v_dry_run         boolean := false;
  v_skip_reason     text := NULL;
  v_emoji           text;
  v_formatted_msg   text;
  v_request_id      bigint;
  v_alert_id        uuid;
  v_dispatch_status text;
  v_result          jsonb;
  v_now             timestamptz := now();
  v_now_brt         text;
BEGIN
  -- Input validation
  IF p_alert_key IS NULL OR p_alert_key = '' THEN
    RAISE EXCEPTION 'alert_key is required';
  END IF;
  IF p_severity IS NULL OR p_severity = '' THEN
    RAISE EXCEPTION 'severity is required';
  END IF;

  v_severity_rank := zapp.fn_severity_rank(p_severity);
  v_now_brt := to_char(v_now AT TIME ZONE 'America/Sao_Paulo', 'DD/MM/YYYY HH24:MI:SS') || ' BRT';

  -- Cooldown check (com escalation bypass)
  SELECT * INTO v_cooldown_row
  FROM zapp.evolution_alert_cooldown
  WHERE alert_key = p_alert_key;

  IF v_cooldown_row.alert_key IS NOT NULL AND NOT p_force_send THEN
    -- Mesma severidade ou downgrade, dentro da janela de cooldown → skip
    IF v_severity_rank <= v_cooldown_row.last_severity_rank
       AND v_now - v_cooldown_row.last_sent_at < make_interval(mins => p_cooldown_min) THEN
      v_skip_reason := format('cooldown_active: %s remaining',
        make_interval(mins => p_cooldown_min) - (v_now - v_cooldown_row.last_sent_at));
      RETURN jsonb_build_object(
        'dispatched', false,
        'skip_reason', v_skip_reason,
        'alert_key', p_alert_key,
        'severity', p_severity,
        'cooldown_until', v_cooldown_row.last_sent_at + make_interval(mins => p_cooldown_min)
      );
    END IF;
  END IF;

  -- Lookup vault secrets (graceful: se faltar, vai pra DRY-RUN)
  BEGIN
    v_webhook_url := zapp.fn_get_vault_secret('bitrix24_webhook_alerts_url');
  EXCEPTION WHEN OTHERS THEN
    v_webhook_url := NULL;
  END;
  BEGIN
    v_recipient_id := zapp.fn_get_vault_secret('bitrix24_alert_recipient_user_id');
  EXCEPTION WHEN OTHERS THEN
    v_recipient_id := NULL;
  END;

  IF v_webhook_url IS NULL OR v_webhook_url = '' OR v_recipient_id IS NULL OR v_recipient_id = '' THEN
    v_dry_run := true;
    v_dispatch_status := 'dry_run_no_secret';
  END IF;

  -- Format message (BB-code Bitrix24)
  v_emoji := CASE
    WHEN v_severity_rank >= 3 THEN '🚨'
    WHEN v_severity_rank = 2 THEN '🟠'
    WHEN v_severity_rank = 1 THEN '⚠️'
    ELSE 'ℹ️'
  END;

  v_formatted_msg := format(
    E'%s [B]%s[/B] · Pipeline ZAPP\n\n[B]📌 %s[/B]\n\n%s\n\n[I]🔑 alert_key:[/I] %s\n[I]🕐 %s[/I]\n[I]🌎 supabase.atomicabr.com.br[/I]',
    v_emoji,
    upper(p_severity),
    coalesce(p_title, '(sem título)'),
    coalesce(p_message, '(sem mensagem)'),
    p_alert_key,
    v_now_brt
  );

  -- Dispatch via pg_net se não for dry-run
  IF NOT v_dry_run THEN
    BEGIN
      v_request_id := net.http_post(
        url := rtrim(v_webhook_url, '/') || '/im.message.add.json',
        body := jsonb_build_object(
          'USER_ID', v_recipient_id,
          'MESSAGE', v_formatted_msg
        ),
        headers := '{"Content-Type": "application/json"}'::jsonb,
        timeout_milliseconds := 5000
      );
      v_dispatch_status := 'sent';
    EXCEPTION WHEN OTHERS THEN
      v_request_id := NULL;
      v_dispatch_status := 'send_failed: ' || SQLERRM;
    END;
  END IF;

  -- Always log in evolution_alerts
  INSERT INTO zapp.evolution_alerts (alert_type, severity, title, message, payload)
  VALUES (
    'bitrix_dispatch',
    p_severity,
    p_title,
    p_message,
    p_payload
      || jsonb_build_object(
        'alert_key', p_alert_key,
        'dispatch_status', v_dispatch_status,
        'dry_run', v_dry_run,
        'http_request_id', v_request_id,
        'severity_rank', v_severity_rank,
        'sent_at', v_now,
        'formatted_msg', v_formatted_msg
      )
  )
  RETURNING id INTO v_alert_id;

  -- Upsert cooldown
  INSERT INTO zapp.evolution_alert_cooldown
    (alert_key, last_severity, last_severity_rank, consecutive_count, last_sent_at,
     last_payload, cooldown_minutes, last_dispatch_status, updated_at)
  VALUES
    (p_alert_key, p_severity, v_severity_rank, 1, v_now,
     p_payload, p_cooldown_min, v_dispatch_status, v_now)
  ON CONFLICT (alert_key) DO UPDATE SET
    last_severity = EXCLUDED.last_severity,
    last_severity_rank = EXCLUDED.last_severity_rank,
    consecutive_count = CASE
      WHEN evolution_alert_cooldown.last_severity = EXCLUDED.last_severity
      THEN evolution_alert_cooldown.consecutive_count + 1
      ELSE 1
    END,
    last_sent_at = EXCLUDED.last_sent_at,
    last_payload = EXCLUDED.last_payload,
    last_dispatch_status = EXCLUDED.last_dispatch_status,
    updated_at = EXCLUDED.updated_at;

  v_result := jsonb_build_object(
    'dispatched', NOT v_dry_run AND v_request_id IS NOT NULL,
    'dry_run', v_dry_run,
    'alert_id', v_alert_id,
    'http_request_id', v_request_id,
    'dispatch_status', v_dispatch_status,
    'severity', p_severity,
    'severity_rank', v_severity_rank,
    'alert_key', p_alert_key,
    'sent_at', v_now,
    'formatted_msg_preview', left(v_formatted_msg, 200)
  );

  RETURN v_result;
END;

DECLARE
  rec RECORD;
  v_decrypted text;
  v_ok int := 0;
  v_fail int := 0;
  v_defer int := 0;
  v_failed_names text[] := '{}';
BEGIN
  FOR rec IN SELECT name, description FROM vault.secrets ORDER BY name
  LOOP
    IF rec.description LIKE 'DEFER%' THEN
      v_defer := v_defer + 1;
    ELSE
      BEGIN
        SELECT decrypted_secret INTO v_decrypted FROM vault.decrypted_secrets WHERE name = rec.name;
        IF v_decrypted IS NOT NULL AND v_decrypted != '' THEN
          v_ok := v_ok + 1;
        ELSE
          v_fail := v_fail + 1;
          v_failed_names := v_failed_names || rec.name;
        END IF;
      EXCEPTION WHEN OTHERS THEN
        v_fail := v_fail + 1;
        v_failed_names := v_failed_names || rec.name;
      END;
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'checked_at', now(),
    'ok', v_ok,
    'fail', v_fail,
    'defer', v_defer,
    'failed_names', to_jsonb(v_failed_names),
    'status', CASE WHEN v_fail = 0 THEN 'healthy' ELSE 'degraded' END
  );
END

DECLARE
  v_contact_type  text;
  v_supabase_url  text;
  v_service_key   text;
  v_resp          bigint;
BEGIN
  IF NEW.sender = 'agent' AND NEW.channel_type = 'internal_chat' THEN
    SELECT contact_type INTO v_contact_type
      FROM zapp.contacts WHERE id = NEW.contact_id;

    IF v_contact_type = 'sicoob_gifts' THEN
      v_supabase_url := COALESCE(
        NULLIF(current_setting('app.settings.supabase_url', true), ''),
        'https://supabase.atomicabr.com.br'
      );

      -- JWT do Vault (elimina GUC service_role_key)
      SELECT decrypted_secret INTO v_service_key
        FROM vault.decrypted_secrets
       WHERE name = 'supabase_service_role_key' LIMIT 1;

      IF v_service_key IS NULL THEN
        RAISE WARNING '[notify_sicoob_on_reply] JWT nao encontrado no vault';
        RETURN NEW;
      END IF;

      BEGIN
        SELECT net.http_post(
          url     := v_supabase_url || '/functions/v1/sicoob-bridge-reply',
          body    := jsonb_build_object(
            'contact_id',  NEW.contact_id,
            'content',     NEW.content,
            'message_id',  NEW.id,
            'agent_id',    NEW.agent_id,
            'created_at',  NEW.created_at
          ),
          headers := jsonb_build_object(
            'Content-Type',  'application/json',
            'Authorization', 'Bearer ' || v_service_key
          )
        ) INTO v_resp;
      EXCEPTION WHEN OTHERS THEN
        RAISE WARNING '[notify_sicoob_on_reply] http_post falhou: % / %', SQLSTATE, SQLERRM;
      END;
    END IF;
  END IF;
  RETURN NEW;
END;
